import fs from 'node:fs'
const md = fs.readFileSync(process.argv[2], 'utf8')
const lines = md.split('\n')
const parts = []
let branch = null, part = null, buf = [], fence = null, code = []
const flushProse = () => {
  const t = buf.join('\n').trim()
  if (t && part) t.split(/\n\s*\n/).forEach(p => part.blocks.push({ kind: 'prose', text: p.replace(/\n/g, ' ').replace(/`/g, '').replace(/\*\*/g, '') }))
  buf = []
}
for (const line of lines) {
  if (fence) {
    if (line.startsWith('```')) {
      let text = code.join('\n')
      if (fence === 'json') { try { text = JSON.stringify(JSON.parse(text), null, 2) } catch {} }
      if (part) part.blocks.push(fence === 'mermaid' ? { kind: 'mermaid', text } : { kind: 'mono', text })
      fence = null; code = []
    } else code.push(line)
    continue
  }
  if (line.startsWith('```')) { flushProse(); fence = line.slice(3).trim() || 'text'; continue }
  let m
  if ((m = line.match(/^## (\d+) (.*)/))) { flushProse(); branch = { n: m[1], title: m[2] }; part = null; continue }
  if ((m = line.match(/^### (\d+\.\d+) (.*)/))) { flushProse(); part = { branch: branch.n, branchTitle: branch.title, n: m[1], title: m[2], blocks: [] }; parts.push(part); continue }
  if (line.startsWith('---') || line.startsWith('# ')) { flushProse(); continue }
  buf.push(line)
}
flushProse()
