export const container = "article.post";
export const ignores = [{ selector: "p.divider", reason: "decorative ornament divider" }];
export const inventory = [
  { selector: "h1", role: "title" },
  { selector: "p", role: "unit" },
  { selector: "figure", role: "unit" },
  { selector: "pre", role: "unit" }
];
export function extract($, toMarkdown) {
  const c = $(container);
  const title = c.find("h1").first().text().trim();
  const units = [];
  c.find("p, pre, figure").each((_, el) => {
    const e = $(el);
    if (e.hasClass("divider")) return;
    if (el.tagName === "figure") {
      const img = e.find("img");
      units.push({ type: "image", src: img.attr("src"), alt: img.attr("alt") || "", element: e });
    } else {
      units.push({ type: "paragraph", display: toMarkdown(e.clone()), element: e });
    }
  });
  return { title, units };
}
